def omega(n):
    if n < 1:
        raise ValueError
    cnt = 0
    m = n
    d = 2
    while d * d <= m:
        if m % d == 0:
            cnt += 1
            while m % d == 0:
                m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        cnt += 1
    return cnt

EXPECTED_COUNT = 17
EXPECTED_FIRST = 2
EXPECTED_LAST = 30

def verify():
    S = []
    for n in range(1, 30):
        ok = True
        for j in (1, 2, 3, 4, 5, 6, 7, 8):
            if omega(n - j) > j:
                ok = False
                break
        if ok:
            S.append(n)
    if len(S) != EXPECTED_COUNT:
        return False
    if S[0] != EXPECTED_FIRST or S[-1] != EXPECTED_LAST:
        return False
    for i in range(len(S) - 1):
        if S[i] >= S[i + 1]:
            return False
    for n in S:
        for j in (1, 2, 3, 4, 5, 6, 7, 8):
            if omega(n - j) > j:
                return False
    return True

def main():
    return 0 if verify() else 1
